/bin/zsh -lc "python3 - <<'PY'
import json, os, stat
from pathlib import Path, PurePosixPath
manifest = json.loads(Path('supplied.json').read_text())
root = Path('payload')
print('Manifest entries:', len(manifest['files']))
print('Declared file_count matches:', manifest['file_count'] == len(manifest['files']))
for name in manifest['files']:
    path = PurePosixPath(name)
    if path.is_absolute() or '..' in path.parts:
        print('SKIPPED escaping path:', name)
    else:
        print('In-scope manifest entry:', name)
try:
    mode = root.lstat().st_mode
except FileNotFoundError:
    print('payload/ does not exist')
else:
    if not stat.S_ISDIR(mode):
        print('payload/ is not a regular directory; not traversed')
    else:
        def scan(directory):
            with os.scandir(directory) as entries:
                for entry in sorted(entries, key=lambda e: e.name):
                    relative = Path(entry.path).relative_to(root)
                    if entry.is_symlink():
                        print('Payload symlink (not followed):', relative)
                    elif entry.is_dir(follow_symlinks=False):
                        scan(entry.path)
                    elif entry.is_file(follow_symlinks=False):
                        print('Payload file not covered by manifest:', relative)
                    else:
                        print('Payload special entry (not read):', relative)
        scan(root)
PY"

